mapper.update:
UPDATE sys_user
nickname = #{nickname}, username = #{username}, phone = #{phone}, email = #{email}, sex = #{sex}, password = #{password}, salt = #{salt}, avatar = #{avatar}, intro = #{intro}, status = #{status}, delete_flag = #{deleteFlag}, lock_flag = #{lockFlag}, lock_time = #{lockTime}, website = #{website}, github = #{github}, update_time = #{updateTime}, login_ip = #{loginIp}, login_agent = #{loginAgent}, login_time = #{loginTime},
WHERE id = #{id}

mapper.select:
SELECT * FROM sys_user
WHERE id IN

    #{id}

select u.*, r.id r_id, r.role_name, r.role_key from sys_user u LEFT JOIN sys_user_role ur ON u.id = ur.user_id LEFT JOIN sys_role r ON ur.role_id = r.id
AND u.nickname LIKE CONCAT('%', #{nickname}, '%')
AND ( u.username LIKE CONCAT('%', #{search}, '%') OR u.phone LIKE CONCAT('%', #{search}, '%') OR u.email LIKE CONCAT('%', #{search}, '%') )
AND u.status = #{status}
AND u.create_time BETWEEN #{begin} AND #{end}
AND
ur.user_id IS NULL
r.role_key = #{role}
ORDER BY create_time ASC

